#!/usr/bin/env python3
# DISCLAIMER: mostly generated by AI agents
import os, shutil, subprocess, re, csv, argparse
from collections import defaultdict
from PyFoam.RunDictionary.ParsedParameterFile import ParsedParameterFile

def parse_args():
    parser = argparse.ArgumentParser(
        description="Run weak scaling study on coupled matrix solution implementations",
        epilog="Example:"
        """
        uv run weak_scaling.py 
        --base-nx 250 
        --base-single-core-time Native=0.1 PetSc=0.3 
        --cmd "apptainer run <container>.sif \'cd $FOAM_FOAMUT; ./Alltest --no-serial -d yes\'"
        --cpu-counts 4 16 32 48 96
        """)
    parser.add_argument(
        "--base-nx", type=int, required=True,
        help="Base mesh size in x-direction (nx) for a single processor"
    )
    parser.add_argument(
        "--base-single-core-time", type=str, nargs="+", required=True,
        help="Baseline single-core runtimes per implementation in seconds, e.g., Native=0.1 PetSc=0.3"
    )
    parser.add_argument(
        "--cmd", type=str, required=True,
        help="Shell command to run the benchmark, quoted"
    )
    parser.add_argument(
        "--cpu-counts", type=int, nargs="+", required=True,
        help="List of processor counts to run, e.g., 4 8 12 16"
    )
    return parser.parse_args()
def parse_timings(raw_list):
    result = {}
    for item in raw_list:
        try:
            k, v = item.split("=")
            result[k.strip()] = float(v)
        except ValueError:
            raise argparse.ArgumentTypeError(f"Invalid format for --base-single-core-time: '{item}'")
    return result

args = parse_args()
impl_baselines = parse_timings(args.base_single_core_time)
command = args.cmd
proc_list = args.cpu_counts
base_nx = args.base_nx
decompose_dict = ParsedParameterFile("cases/theCase/system/decomposeParDict")
mesh_dict = ParsedParameterFile("cases/theCase/system/blockMeshDict")
results = {}

for nprocs in proc_list:
    print(f"\n=== Running weak scaling with {nprocs} processors ===")

    # 1. Update decomposeParDict
    decompose_dict["numberOfSubdomains"] = nprocs
    print([4, int(nprocs/4), 1] )
    decompose_dict["hierarchicalCoeffs"]['n'] = [4, int(nprocs/4), 1]
    decompose_dict.writeFile()

    # 2. Update blockMeshDict (scale nx linearly)
    nx = int(base_nx * nprocs)
    print(f"{nx}x{nx} mesh, {nx*nx/1e6:.3f}M total cell count")
    mesh_dict["blocks"] = [ f"hex (0 1 2 3 4 5 6 7) ({nx} {nx} 1) simpleGrading (1 1 1)" ]
    mesh_dict.writeFile()

    # 3. Clean foamUT temp dir
    tmp_path = "/tmp/foamUTCases"
    if os.path.exists(tmp_path):
        print(f"Removing {tmp_path}")
        shutil.rmtree(tmp_path)

    # 4. Run test and capture output
    try:
        ansi_escape = re.compile(r'\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])')
        proc = subprocess.run(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            shell=True
        )

        # 5. Extract timing info
        lines = [ansi_escape.sub('', line) for line in proc.stdout.splitlines()]
        timings = [line for line in lines if "implementation of coupled equations" in line]
        errors = [line for line in lines if "ERROR:" in line]
        if errors:
            raise ValueError(f"Some test cases errored out:\n{"\n".join(errors)}")
        timings = sorted(set(timings))

        for timing in timings:
            print(f"[{nprocs} procs] {timing}")

        results[nprocs] = timings

    except Exception as e:
        print(f"Error during run with {nprocs} processors: {e}")

aggregated = []
all_impls = set()
for timings in results.values():
    for line in timings:
        match = re.search(r"([\d.]+) s: (.+?) implementation", line)
        if match:
            all_impls.add(match.group(2).strip())
all_impls = sorted(all_impls)

for nprocs, timing_lines in results.items():
    impl_timings = defaultdict(list)
    for line in timing_lines:
        match = re.search(r"([\d.]+) s: (.+?) implementation", line)
        if match:
            time = float(match.group(1))
            impl = match.group(2).strip()
            impl_timings[impl].append(time)

    row = {
        "nprocs": nprocs,
        "n_cells": (base_nx * (nprocs // 4))**2  # assumes 2D mesh
    }

    for impl in all_impls:
        times = impl_timings.get(impl, [])
        avg_time = sum(times) / len(times) if times else None
        if avg_time:
            row[impl] = round(avg_time, 6)
            base_time = impl_baselines.get(impl)
            if base_time:
                row[f"{impl}_eff"] = round(base_time / avg_time, 4)
            else:
                row[f"{impl}_eff"] = ""
        else:
            row[impl] = ""
            row[f"{impl}_eff"] = ""
    aggregated.append(row)

# Write to CSV
fieldnames = ["nprocs", "n_cells"] + all_impls + [f"{impl}_eff" for impl in all_impls]
with open("weak_scaling_results.csv", "w", newline="") as csvfile:
    writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(aggregated)
